package fetcher

import (
	"io"
	"net/http"
)

// FetchURL fetches the body of a URL and returns it as a string.
func FetchURL(url string) (string, error) {
	resp, err := http.Get(url)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

package fetcher

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestFetchURL(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("hello"))
	}))
	defer ts.Close()
	body, err := FetchURL(ts.URL)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if body != "hello" {
		t.Fatalf("want hello, got %q", body)
	}
}

func TestFetchURL_NotFound(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(404)
		w.Write([]byte("not found"))
	}))
	defer ts.Close()
	body, err := FetchURL(ts.URL)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if body != "not found" {
		t.Fatalf("want 'not found', got %q", body)
	}
}

func TestFetchURL_InvalidURL(t *testing.T) {
	_, err := FetchURL("http://localhost:0/invalid")
	if err == nil {
		t.Fatal("expected error for invalid URL")
	}
}

